class PhotobookOrderModel {
  final String orderNumber, productName, designTitle, paymentStatus, productionStatus, shippingStatus, orderStatus, finalPdfStatus;
  final int pageCount, printQuantity, totalAmount; final bool printFileReady; final String? jntAwb, createdAt;
  PhotobookOrderModel({required this.orderNumber,required this.productName,required this.designTitle,required this.pageCount,required this.printQuantity,required this.totalAmount,required this.paymentStatus,required this.productionStatus,required this.shippingStatus,required this.orderStatus,required this.finalPdfStatus,required this.printFileReady,this.jntAwb,this.createdAt});
  factory PhotobookOrderModel.fromJson(Map<String,dynamic> j)=>PhotobookOrderModel(orderNumber:(j['order_number']??'-').toString(),productName:(j['product_name']??'-').toString(),designTitle:(j['design_title']??'-').toString(),pageCount:(j['page_count'] as num?)?.toInt()??0,printQuantity:(j['print_quantity'] as num?)?.toInt()??0,totalAmount:(j['total_amount'] as num?)?.toInt()??0,paymentStatus:(j['payment_status']??'-').toString(),productionStatus:(j['production_status']??'-').toString(),shippingStatus:(j['shipping_status']??'-').toString(),orderStatus:(j['order_status']??'-').toString(),finalPdfStatus:(j['final_pdf_status']??'-').toString(),printFileReady:j['print_file_ready']==true||j['print_file_ready']==1,jntAwb:j['jnt_awb']?.toString(),createdAt:j['created_at']?.toString());
